SELECT AVG(CAST((taxpayer_10.average_medicare_allowed_amt - taxpayer_10.average_medicare_payment_amt) AS double precision)) AS avg_calculation_9940518082838207_ok,   taxpayer_10.nppes_provider_first_name AS nppes_provider_first_name FROM taxpayer_10 WHERE ((taxpayer_10.hcpcs_description = 'Initial hospital care') AND (taxpayer_10.nppes_provider_city IN ('BELLEVUE', 'BELLVUE')) AND (taxpayer_10.nppes_provider_state = 'WA')) GROUP BY taxpayer_10.nppes_provider_first_name;
